// build-ledger.mjs
// Pure core of the registry sync: text in, YAML string out. No filesystem, no
// process.env, no side effects on import. The thin shell (sync-registry.mjs)
// reads the files, calls buildLedger, and writes the single registry/ledger.yaml.
//
// Input snapshot shape (all file contents already read as text):
//   {
//     homeDir:        string,            // for resolving ~ in local sources
//     repoRoot:       string,            // for the local-source self check
//     globalLockText: string | null,     // ~/.agents/.skill-lock.json
//     projects:       [{ path, lockText: string | null }],  // resolved dir + its skills-lock.json
//     forks:          [{ skill, metaText: string }],         // registry/upstream/<skill>/meta.yaml
//   }

import path from 'node:path';

// Sources that mean "this is my own skill", not third-party.
const SELF_SOURCES = new Set(['jfmoe/skills']);
const SELF_URL_FRAGMENT = 'jfmoe/skills';

// The shell that writes the ledger; recorded in the ledger header.
export const GENERATED_BY = 'skills/manage-skills/scripts/sync-registry.mjs';

function expandHome(p, homeDir) {
  if (!p) return p;
  return p.replace(/^~(?=$|\/)/, homeDir);
}

function parseJson(text) {
  if (text == null) return null;
  try {
    return JSON.parse(text);
  } catch {
    return null;
  }
}

// --- parsers (pure, text in) ------------------------------------------------

// projects.yaml is a flat YAML list of paths. Strips comments and quotes.
export function parseProjectsYaml(text) {
  const out = [];
  for (const raw of (text || '').split(/\r?\n/)) {
    const line = raw.replace(/#.*$/, '').trimEnd();
    const m = line.match(/^\s*-\s*(.+?)\s*$/);
    if (m) out.push(m[1].replace(/^['"]|['"]$/g, ''));
  }
  return out;
}

// meta.yaml is a top-level `key: value` map. A `key: |` (or `>`) block scalar is
// captured as joined text. (notes is parsed but intentionally absent from the
// ledger — it is human provenance, not inventory data.)
export function parseMetaYaml(text) {
  const obj = {};
  if (!text) return obj;
  const lines = text.split(/\r?\n/);
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^([A-Za-z0-9_]+):\s*(.*)$/);
    if (!m) continue;
    const key = m[1];
    const val = m[2];
    if (val === '|' || val === '>') {
      const block = [];
      while (i + 1 < lines.length && /^\s+\S/.test(lines[i + 1])) {
        block.push(lines[++i].replace(/^\s+/, ''));
      }
      obj[key] = block.join('\n');
    } else {
      obj[key] = val.replace(/^['"]|['"]$/g, '');
    }
  }
  return obj;
}

// --- classification ---------------------------------------------------------

export function isSelf(entry, repoRoot, homeDir) {
  if (!entry) return false;
  const src = entry.source || '';
  if (SELF_SOURCES.has(src)) return true;
  if ((entry.sourceUrl || '').includes(SELF_URL_FRAGMENT)) return true;
  if (entry.sourceType === 'local') {
    const resolved = path.resolve(expandHome(src, homeDir));
    if (resolved === repoRoot) return true;
  }
  return false;
}

// --- collectors (snapshot in, camelCase rows out) ---------------------------

function collectGlobal(raw) {
  const lock = parseJson(raw.globalLockText);
  const rows = [];
  if (lock && lock.skills) {
    for (const [name, entry] of Object.entries(lock.skills)) {
      if (isSelf(entry, raw.repoRoot, raw.homeDir)) continue;
      rows.push({
        name,
        source: entry.source || '',
        sourceUrl: entry.sourceUrl || '',
        skillPath: entry.skillPath || '',
        updatedAt: entry.updatedAt || '',
      });
    }
  }
  rows.sort((a, b) => a.name.localeCompare(b.name));
  return rows;
}

function collectProjects(raw) {
  const rows = [];
  const issues = [];
  for (const { path: proj, lockText } of raw.projects || []) {
    if (lockText == null) {
      issues.push({ project: proj, reason: 'no skills-lock.json' });
      continue;
    }
    const lock = parseJson(lockText);
    if (!lock || !lock.skills) {
      issues.push({ project: proj, reason: 'unreadable skills-lock.json' });
      continue;
    }
    for (const [name, entry] of Object.entries(lock.skills)) {
      if (isSelf(entry, raw.repoRoot, raw.homeDir)) continue;
      rows.push({
        project: proj,
        name,
        source: entry.source || '',
        skillPath: entry.skillPath || '',
      });
    }
  }
  rows.sort((a, b) => a.project.localeCompare(b.project) || a.name.localeCompare(b.name));
  return { rows, issues };
}

function collectForks(raw) {
  const rows = (raw.forks || []).map(({ skill, metaText }) => {
    const meta = parseMetaYaml(metaText);
    return {
      skill,
      source: meta.source || '',
      ref: meta.ref || '',
      commit: meta.commit || '',
      upstreamPath: meta.upstream_path || '',
      localPath: meta.local_path || '',
      fetchedAt: meta.fetched_at || '',
    };
  });
  rows.sort((a, b) => a.skill.localeCompare(b.skill));
  return rows;
}

// Assemble the four record sets (camelCase, mirroring the old inventory.json).
// Exported so the golden test can compare records directly.
export function assembleLedger(raw) {
  const globalThirdParty = collectGlobal(raw);
  const { rows: projectThirdParty, issues: projectScanIssues } = collectProjects(raw);
  const forks = collectForks(raw);
  return { globalThirdParty, projectThirdParty, projectScanIssues, forks };
}

// --- YAML emitter (hand-rolled, zero deps) ----------------------------------
// Rule: every scalar is double-quoted and escaped. No "does this need quoting"
// heuristics. Handles our document shape only: a top-level map whose values are
// scalars, empty arrays, or arrays of flat maps.

function quoteScalar(value) {
  const escaped = String(value ?? '')
    .replace(/\\/g, '\\\\')
    .replace(/"/g, '\\"')
    .replace(/\n/g, '\\n')
    .replace(/\r/g, '\\r')
    .replace(/\t/g, '\\t');
  return `"${escaped}"`;
}

export function emitYaml(doc) {
  const lines = [];
  for (const [key, value] of Object.entries(doc)) {
    if (Array.isArray(value)) {
      if (value.length === 0) {
        lines.push(`${key}: []`);
        continue;
      }
      lines.push(`${key}:`);
      for (const item of value) {
        Object.entries(item).forEach(([k, v], idx) => {
          lines.push(`${idx === 0 ? '  - ' : '    '}${k}: ${quoteScalar(v)}`);
        });
      }
    } else {
      lines.push(`${key}: ${quoteScalar(value)}`);
    }
  }
  return lines.join('\n') + '\n';
}

// --- public entry point -----------------------------------------------------

export function buildLedger(raw) {
  const { globalThirdParty, projectThirdParty, projectScanIssues, forks } = assembleLedger(raw);
  const doc = {
    generated_by: GENERATED_BY,
    global_third_party: globalThirdParty.map((r) => ({
      name: r.name,
      source: r.source,
      source_url: r.sourceUrl,
      skill_path: r.skillPath,
      updated_at: r.updatedAt,
    })),
    project_third_party: projectThirdParty.map((r) => ({
      project: r.project,
      name: r.name,
      source: r.source,
      skill_path: r.skillPath,
    })),
    project_scan_issues: projectScanIssues.map((r) => ({
      project: r.project,
      reason: r.reason,
    })),
    forks: forks.map((r) => ({
      skill: r.skill,
      source: r.source,
      ref: r.ref,
      commit: r.commit,
      upstream_path: r.upstreamPath,
      local_path: r.localPath,
      fetched_at: r.fetchedAt,
    })),
  };
  return emitYaml(doc);
}

#!/usr/bin/env node
// sync-registry.mjs
// Thin IO shell around build-ledger.mjs: discover + read the input files, hand
// their text to the pure core, and write the single registry/ledger.yaml.
//
// Inputs (nothing here is hand-maintained except registry/projects.yaml):
//   - registry/projects.yaml                project paths to scan (the only manual input)
//   - ~/.agents/.skill-lock.json            global install lock (source of global third-party)
//   - <project>/skills-lock.json            per-project install lock (source of project third-party)
//   - registry/upstream/<skill>/meta.yaml   fork provenance
//
// Output (generated — never hand-edit):
//   - registry/ledger.yaml                  single YAML ledger (full field set)
//
// Usage:
//   node skills/manage-skills/scripts/sync-registry.mjs [repoRoot]
//   SKILLS_REPO=/path/to/repo node .../sync-registry.mjs
//
// Output is deterministic (sorted, no timestamps) so reruns produce clean git diffs.

import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

import { assembleLedger, buildLedger, parseProjectsYaml } from './build-ledger.mjs';

const HOME = os.homedir();

function expandHome(p) {
  if (!p) return p;
  return p.replace(/^~(?=$|\/)/, HOME);
}

function readTextOrNull(file) {
  try {
    return fs.readFileSync(file, 'utf8');
  } catch {
    return null;
  }
}

function looksLikeRepo(p) {
  return !!p && fs.existsSync(path.join(p, 'registry')) && fs.existsSync(path.join(p, 'skills'));
}

// Walk up from a starting directory until we find a dir that looks like the repo
// root. Depth-robust: it does not assume how deeply the script is nested, so the
// script keeps working wherever the skill folder is moved.
function findRepoRootUpward(startDir) {
  let dir = path.resolve(startDir);
  for (;;) {
    if (looksLikeRepo(dir)) return dir;
    const parent = path.dirname(dir);
    if (parent === dir) return null; // reached the filesystem root
    dir = parent;
  }
}

function resolveRepoRoot() {
  const scriptDir = path.dirname(new URL(import.meta.url).pathname);
  const walked = findRepoRootUpward(scriptDir);
  const candidates = [process.argv[2], process.env.SKILLS_REPO, walked, path.join(HOME, 'Coder/skills')]
    .filter(Boolean)
    .map((c) => path.resolve(expandHome(c)));
  for (const c of candidates) {
    if (looksLikeRepo(c)) return c;
  }
  throw new Error('Could not locate the skills repo root. Pass it as the first argument or set SKILLS_REPO.');
}

// Read every input file as text and assemble the snapshot the pure core expects.
function readSnapshot(repoRoot) {
  const globalLockText = readTextOrNull(path.join(HOME, '.agents/.skill-lock.json'));

  const projectPaths = parseProjectsYaml(readTextOrNull(path.join(repoRoot, 'registry/projects.yaml')) || '');
  const projects = projectPaths.map((projRaw) => {
    const proj = path.resolve(expandHome(projRaw));
    return { path: proj, lockText: readTextOrNull(path.join(proj, 'skills-lock.json')) };
  });

  const forks = [];
  const upstreamDir = path.join(repoRoot, 'registry/upstream');
  if (fs.existsSync(upstreamDir)) {
    for (const name of fs.readdirSync(upstreamDir)) {
      const skillDir = path.join(upstreamDir, name);
      if (!fs.statSync(skillDir).isDirectory()) continue;
      const metaText = readTextOrNull(path.join(skillDir, 'meta.yaml'));
      if (metaText == null) continue;
      forks.push({ skill: name, metaText });
    }
  }

  return { homeDir: HOME, repoRoot, globalLockText, projects, forks };
}

// --- main ---

const repoRoot = resolveRepoRoot();
const snapshot = readSnapshot(repoRoot);

fs.writeFileSync(path.join(repoRoot, 'registry/ledger.yaml'), buildLedger(snapshot));

const { globalThirdParty, projectThirdParty, projectScanIssues, forks } = assembleLedger(snapshot);
console.error(
  `synced registry: ${globalThirdParty.length} global, ${projectThirdParty.length} project, ${forks.length} fork(s); ` +
    `${projectScanIssues.length} scan note(s)`,
);

